import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== CORE STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [showSystemResponse, setShowSystemResponse] = useState(false);
  const [systemResponseMessage, setSystemResponseMessage] = useState('');
  const [myPhone, setMyPhone] = useState('0712345678');
  const [isFirstTimeUser, setIsFirstTimeUser] = useState(true);
  const [showWelcomeBack, setShowWelcomeBack] = useState(false);
  const [registrationError, setRegistrationError] = useState('');
  const [userExistsError, setUserExistsError] = useState(false);
  const [showMainMenu, setShowMainMenu] = useState(false);
  const [registrationComplete, setRegistrationComplete] = useState(false);
  const [activationKeyword, setActivationKeyword] = useState('');
  const [isEditingProfile, setIsEditingProfile] = useState(false);

  // ===== DASHBOARD STATE =====
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [currentRequestIndex, setCurrentRequestIndex] = useState(0);
  const [myMatches, setMyMatches] = useState([]);
  const [currentMatchListIndex, setCurrentMatchListIndex] = useState(0);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [isSendingMessage, setIsSendingMessage] = useState(false);
  const [searchCriteria, setSearchCriteria] = useState({ ageRange: '', town: '', county: '' });
  const [matchOffset, setMatchOffset] = useState(0);
  const [totalMatches, setTotalMatches] = useState(0);

  // ===== CHAT STATE =====
  const [chatContacts, setChatContacts] = useState([]);
  const [chatMessages, setChatMessages] = useState({});
  const [newMessage, setNewMessage] = useState('');
  const [selectedChatContact, setSelectedChatContact] = useState(null);

  // ============================================
  // SAMPLE DATA
  // ============================================

  const SAMPLE_MATCHES = [
    { id: 1, phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', county: 'Nairobi County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
    { id: 2, phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', county: 'Nakuru County', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Caring and dedicated. Loves children and education.' },
    { id: 3, phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', county: 'Mombasa County', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', marital_status: 'single', description: 'Ambitious and hardworking. I love numbers.' },
    { id: 4, phone: '0722040506', name: 'Pamela Nafula', age: 26, town: 'Kisumu', county: 'Kisumu County', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Tech enthusiast. Loves innovation and building solutions.' },
    { id: 5, phone: '0702556677', name: 'Maria Mwende', age: 28, town: 'Kasarani', county: 'Nairobi County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Diligent, loving, dedicated and will make you tick.' },
    { id: 6, phone: '0708990011', name: 'Keziah Cheptab', age: 28, town: 'Eldoret', county: 'Uasin Gishu County', profession: 'Doctor', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Passionate about healthcare and community service.' }
  ];

  const SAMPLE_REQUESTS = [
    { id: 101, phone: '0723000001', name: 'Michael Ochieng', age: 30, town: 'Nairobi', county: 'Nairobi County', profession: 'Lawyer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending' },
    { id: 102, phone: '0723000002', name: 'David Kiprop', age: 28, town: 'Eldoret', county: 'Uasin Gishu County', profession: 'Businessman', education: 'Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending' },
    { id: 103, phone: '0723000003', name: 'Samuel Mwangi', age: 32, town: 'Nakuru', county: 'Nakuru County', profession: 'Developer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending' }
  ];

  const SAMPLE_MY_MATCHES = [
    { id: 201, phone: '0724000001', name: 'Grace Akinyi', age: 27, town: 'Kisumu', county: 'Kisumu County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', status: 'accepted' },
    { id: 202, phone: '0724000002', name: 'Peter Mwangi', age: 29, town: 'Nakuru', county: 'Nakuru County', profession: 'Engineer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', status: 'accepted' },
    { id: 203, phone: '0724000003', name: 'Sarah Wanjiru', age: 25, town: 'Thika', county: 'Kiambu County', profession: 'Designer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', status: 'accepted' }
  ];

  // ============================================
  // STEPS DEFINITION
  // ============================================

  const STEPS = [
    {
      id: 1,
      title: 'Service Activation',
      subtitle: 'Enter PENZI to activate',
      icon: '💑',
      fields: [{ key: 'penzi', label: 'Enter Activation Code', placeholder: 'Type PENZI', type: 'text' }],
      isActivation: true,
      userMessage: 'PENZI',
      systemMessage: 'Welcome to our dating service with 6000 potential dating partners!\n\nTo register, enter the following details:\nstart#name#age#gender#county#town\n\nExample:\nstart#John Doe#26#Male#Nakuru#Naivasha'
    },
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
        { key: 'name', label: '👤 Full Name', placeholder: 'Jamal Jalang\'o', type: 'text' },
        { key: 'age', label: '🎂 Age', placeholder: '29', type: 'number' },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
        { key: 'county', label: '📍 County', placeholder: 'Mombasa', type: 'text' },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Bamburi', type: 'text' }
      ],
      isRegistration: true,
      userMessage: (data) => `start#${data.name}#${data.age}#${data.gender}#${data.county}#${data.town}`,
      systemMessage: (data) => `Your profile has been created successfully ${data.name}.\n\nSMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.\nE.g. details#diploma#driver#single#christian#mijikenda`
    },
    {
      id: 3,
      title: 'Details Registration',
      subtitle: 'Complete your profile',
      icon: '📋',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
        { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Muslim', type: 'text' },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Somali', type: 'text' }
      ],
      isDetails: true,
      userMessage: (data) => `details#${data.education_level}#${data.profession}#${data.marital_status}#${data.religion}#${data.ethnicity}`,
      systemMessage: 'This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.\nE.g., MYSELF chocolate, lovely, sexy etc.'
    },
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      fields: [{ key: 'description', label: 'Describe yourself', placeholder: 'tall, dark and handsome', type: 'textarea' }],
      isSelfDescription: true,
      userMessage: (data) => `MYSELF ${data.description}`,
      systemMessage: 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.\nE.g., match#23-25#Kisumu'
    }
  ];

  // ============================================
  // API CALL FUNCTIONS
  // ============================================

  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();
      console.log(`API ${method} ${endpoint}:`, data);
      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ===== API FUNCTIONS FOR MATCHING =====

  const searchMatches = async (phone, ageRange, town) => {
    try {
      const result = await callApi('/match', 'POST', {
        phone: phone,
        ageRange: ageRange,
        town: town,
