      addNotification('❌ Match not found.', 'error');
      return;
    }

    setIsLoading(true);
    try {
      const fromPhone = currentUser?.phone || myPhone || '0712345678';
      const result = await expressInterest(fromPhone, targetPhone);

      if (result && result.status === 'success') {
        addToConversation('📱 You', `Expressing interest in ${match.name}`, false);
        addToConversation('🤖 System', `💕 Interest sent to ${match.name}! They will be notified.`, true);

        const newRequest = {
          id: Date.now(),
          phone: match.phone,
          name: match.name,
          age: match.age,
          town: match.town,
          county: match.county,
          profession: match.profession,
          message: `💕 ${currentUser?.name || 'Someone'} is interested in you!`,
          status: 'pending'
        };
        setIncomingRequests(prev => [...prev, newRequest]);
        setAllMatches(prev => prev.filter(m => m.phone !== targetPhone));
        addNotification(`💕 Interest sent to ${match.name}!`);
      } else {
        addNotification('❌ Failed to send interest. Please try again.', 'error');
