  const loadMatches = async (ageRange, town, county) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      setSearchCriteria({ ageRange, town, county });
      setMatchOffset(0);

      const result = await searchMatches(phone, ageRange, town);

      if (!result || result.length === 0) {
        let filtered = SAMPLE_MATCHES;
        if (ageRange && ageRange !== '') {
          const [min, max] = ageRange.split('-').map(Number);
          if (!isNaN(min) && !isNaN(max)) {
            filtered = filtered.filter(m => m.age >= min && m.age <= max);
          }
        }
        if (town && town !== '') {
          filtered = filtered.filter(m => m.town.toLowerCase().includes(town.toLowerCase()));
        }
        if (county && county !== '') {
          filtered = filtered.filter(m => m.county && m.county.toLowerCase().includes(county.toLowerCase()));
        }
        setAllMatches(filtered);
        addNotification(`✅ Found ${filtered.length} matches!`);
      }
