  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');
    setRegistrationError('');
    setUserExistsError(false);

    try {
      let phone = formData.phone_number || phoneNumber || myPhone || '0712345678';

      // STEP 2: SERVICE REGISTRATION
      if (step.id === 2) {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };
        const result = await callApi('/register', 'POST', data);

        // Check if user already exists
        if (result && result.status === 'error' && result.message === 'User already exists') {
          setRegistrationError('⚠️ User already exists. Proceeding to dashboard.');
          setUserExistsError(true);
          setResponseMessage('⚠️ User already exists');
          setIsSuccess(false);
          addNotification('⚠️ User already exists. Proceeding to dashboard.', 'warning');

          setCompletedSteps(prev => new Set([...prev, currentStep]));
          setMyPhone(formData.phone_number || '0712345678');

          const partialUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(partialUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          setIsLoading(false);
          setRegistrationError('⚠️ User already exists. Proceeding to dashboard.');
          return;
        }

        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage(formData);

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setMyPhone(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
          setRegistrationError('');

          const newUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(newUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setResponseMessage('❌ ' + errorMsg);
          setIsSuccess(false);
          setRegistrationError(errorMsg);
        }
      }

      // STEP 3: DETAILS REGISTRATION
      else if (step.id === 3) {
        const data = {
          education_level: formData.education_level,
          profession: formData.profession,
          marital_status: formData.marital_status,
          religion: formData.religion,
          ethnicity: formData.ethnicity
        };
        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage;

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed!');

          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              education: formData.education_level,
              profession: formData.profession,
              marital_status: formData.marital_status,
              religion: formData.religion,
              ethnicity: formData.ethnicity
            }));
          }
        } else {
          setResponseMessage('❌ ' + (result?.message || 'Profile completion failed.'));
          setIsSuccess(false);
        }
      }

      // STEP 4: SELF-DESCRIPTION
      else if (step.id === 4) {
        const result = await callApi(`/${phone}/self-description`, 'POST', { description: formData.description });
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage;

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Self-description added!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
          setRegistrationComplete(true);

          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              description: formData.description
            }));
          }

          if (!isLoggedIn) {
            const user = {
              phone: formData.phone_number || phone || '0712345678',
              name: formData.name || 'User',
              age: formData.age || '26',
              town: formData.town || 'Nairobi',
              county: formData.county || 'Nairobi',
              description: formData.description
            };
            setCurrentUser(user);
            setIsLoggedIn(true);
          }
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          addNotification('🎉 Welcome to PENZI Dating!');
        } else {
          setResponseMessage('❌ ' + (result?.message || 'Self-description failed.'));
          setIsSuccess(false);
        }
      }

    } catch (error) {
      console.error('❌ API Error:', error);
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;
    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER SYSTEM RESPONSE
  // ============================================

  const renderSystemResponse = () => {
    if (!showSystemResponse || !systemResponseMessage) return null;

    return (
      <div className="system-response-card">
        <div className="response-title">🤖 System Response</div>
        <div className="response-body">{systemResponseMessage}</div>
      </div>
    );
  };

  // ============================================
  // RENDER ACTIVATION STEP
  // ============================================

  const renderActivationStep = () => {
    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="top-actions">
            {/* No exit button on activation page */}
          </div>

          <div className="registration-header">
            <div className="registration-icon">💑</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {renderSmsConversation()}

          <div className="step-info-card">
            <div className="step-number">🔑 ENTRY POINT</div>
            <h2>Service Activation</h2>
            <p>Enter PENZI to activate the service</p>
          </div>

          {!activationDone ? (
            // BEFORE ACTIVATION
            <>
              <div className="activation-hint">
                <div className="hint-bubble">
                  <span className="hint-label">📱 To activate:</span>
                  <span className="hint-code">PENZI</span>
                </div>
              </div>

              <div className="activation-form">
                <div className="input-group">
                  <label>📱 Enter Activation Code</label>
                  <input
                    type="text"
                    value={activationKeyword}
                    onChange={(e) => setActivationKeyword(e.target.value.toUpperCase())}
                    placeholder="Type PENZI"
                    className="input-field"
                    autoFocus
                  />
                </div>

                <div className="activation-actions">
                  <button
                    onClick={activateService}
                    disabled={isLoading || serverStatus === 'error'}
                    className="btn-primary"
                  >
                    {isLoading ? '⏳ Activating...' : '💑 Activate Service'}
                  </button>
                </div>
              </div>

              {errorDetails && (
                <div className="error-details">
                  <p className="error-detail-text">💡 {errorDetails}</p>
                </div>
              )}

              {responseMessage && (
                <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
                  {responseMessage}
                </div>
              )}
            </>
          ) : (
            // AFTER ACTIVATION - System Response + START Button
            <>
              {renderSystemResponse()}

              <div className="activation-success">
                <div className="activation-success-icon">✅</div>
                <p className="activation-success-text">Service activated successfully!</p>

                {/* START BUTTON - Prominently displayed here */}
                <button
                  onClick={proceedToRegistration}
                  className="btn-start"
                >
                  🚀 START
                </button>

                <p style={{ marginTop: '8px', fontSize: '13px', color: '#6b7280' }}>
                  Click START to begin your registration
                </p>
              </div>
            </>
          )}

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION STEPS
  // ============================================

  const renderRegistrationStep = () => {
    const step = STEPS[currentStep];
    const isLastStep = currentStep === STEPS.length - 1;
    const previewSms = buildSmsPreview(step);
    const isActivationStep = step.id === 1;
    const showUserExistsWarning = step.id === 2 && userExistsError;
    const isLastStepCompleted = isLastStep && completedSteps.has(currentStep);
    const hasFields = step.fields && step.fields.length > 0;

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="top-actions">
            {isLoggedIn && (
              <button className="btn-top btn-home" onClick={goHome}>🏠 Home</button>
            )}
            <button className="btn-top btn-exit" onClick={handleLogout}>🚪 Exit</button>
          </div>

          {showWelcomeBack && (
            <div className="welcome-back-banner">
              <div className="welcome-back-icon">👋</div>
              <div className="welcome-back-text">
                <h3>Welcome Back!</h3>
                <p>Continue your dating journey</p>
              </div>
              <button className="btn-primary btn-continue" onClick={() => {
                setIsLoggedIn(true);
                setShowMainMenu(true);
              }}>
                Continue →
              </button>
            </div>
          )}

          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/{STEPS.length}</span>
            </div>
          )}

          {renderSmsConversation()}

          <div className="step-info-card">
            <div className="step-number">Step {currentStep} of {STEPS.length - 1}</div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>

          {renderSystemResponse()}

          {showUserExistsWarning && (
            <div className="user-exists-warning">
              <div className="warning-icon">⚠️</div>
              <div className="warning-content">
                <div className="warning-title">User Already Exists</div>
                <div className="warning-text">{registrationError}</div>
              </div>
            </div>
          )}

          {registrationError && !userExistsError && (
            <div className="registration-error">
              <span className="error-icon">⚠️</span>
              <span className="error-text">{registrationError}</span>
            </div>
          )}

          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">

            {hasFields && step.fields.map((field) => (
              <div key={field.key} className="input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    className="input-field"
                    required={!userExistsError}
                    disabled={userExistsError}
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="textarea-field"
                    rows={4}
                    required={!userExistsError}
                    disabled={userExistsError}
                  />
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                    required={!userExistsError}
                    disabled={userExistsError}
                  />
                )}
              </div>
            ))}

            {previewSms && (
              <div className="sms-preview-container">
                <div className="sms-preview-label">📱 Your SMS will be:</div>
                <div className="sms-preview-content">{previewSms}</div>
              </div>
            )}
          </form>

          {/* Registration Actions */}
          <div className="registration-actions">
            <button
              type="button"
              onClick={() => goToStep(currentStep - 1)}
              disabled={currentStep === 1 || isLoading || !activationDone}
              className="btn-secondary"
            >
              ⬅ Previous
            </button>

            {!userExistsError && hasFields && (
              <button
                type="submit"
                disabled={isLoading || serverStatus === 'error'}
                className={`btn-primary ${isLoading ? 'loading' : ''}`}
                onClick={() => {
                  const allFieldsFilled = step.fields.every(field => 
                    formData[field.key] && formData[field.key].trim() !== ''
                  );
                  if (allFieldsFilled) {
                    executeApi();
                  } else {
                    addNotification('⚠️ Please fill in all fields.', 'warning');
                  }
                }}
              >
                {isLoading ? '⏳ Sending...' : '📤 Send'}
              </button>
            )}

            {/* NEXT Button - Goes to next step OR Dashboard if user exists */}
            <button
              type="button"
              onClick={() => {
                // If user exists error, go directly to dashboard
                if (userExistsError) {
                  setShowMainMenu(true);
                  setIsLoggedIn(true);
                  setUserExistsError(false);
                  setRegistrationError('');
                  return;
                }

                // If on last step and completed, go to menu
                if (isLastStep && completedSteps.has(currentStep)) {
                  setShowMainMenu(true);
                  setIsLoggedIn(true);
                  return;
                }

                // Otherwise go to next step
                if (currentStep < STEPS.length - 1) {
                  setCurrentStep(currentStep + 1);
                }
              }}
              disabled={isLoading || (currentStep === 1 && !completedSteps.has(currentStep) && !userExistsError)}
              className="btn-secondary"
            >
              {userExistsError ? '📋 Go to Dashboard' :
               isLastStep && completedSteps.has(currentStep) ? '📋 Go to Menu' : 
               isLastStep ? '📋 Go to Menu' : 'Next ➡'}
            </button>
          </div>

          {userExistsError && (
            <div className="user-exists-help">
              <p>💡 You can click <strong>📋 Go to Dashboard</strong> to proceed to find matches.</p>
            </div>
          )}

          {isLastStep && completedSteps.has(currentStep) && !userExistsError && (
            <div className="registration-complete-prompt">
              <p>🎉 Registration complete! Click <strong>📋 Go to Menu</strong> to continue.</p>
            </div>
          )}

          {errorDetails && (
            <div className="error-details">
              <p className="error-detail-text">💡 {errorDetails}</p>
            </div>
          )}

          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              {responseMessage}
            </div>
          )}

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

